package com.dy.artisan3d.util// NetworkExtensions.ktimport com.dy.artisan3d.domain.model.NetworkErrorimport io.ktor.client.plugins.*import kotlinx.serialization.SerializationExceptionsuspend fun <T> safeApiCall(    apiCall: suspend () -> T): Result<T> {    return try {        Result.success(apiCall())    } catch (e: Exception) {        Result.failure(e.toNetworkError())    }}fun Exception.toNetworkError(): NetworkError {    return when (this) {        is HttpRequestTimeoutException -> NetworkError.RequestTimeout // REQUEST_TIMEOUT emas        is ClientRequestException -> {            when (response.status.value) {                401 -> NetworkError.Unauthorized                409 -> NetworkError.Conflict                413 -> NetworkError.PayloadTooLarge                429 -> NetworkError.TooManyRequests                else -> NetworkError.Unknown            }        }        is ServerResponseException -> NetworkError.ServerError        is SerializationException -> NetworkError.Serialization        is io.ktor.utils.io.errors.IOException -> NetworkError.NoInternet        else -> NetworkError.Unknown    }}